fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn median(mut x:Vec<f64>)->f64{assert!(!x.is_empty());x.sort_by(f64::total_cmp);let n=x.len();if n%2==1{x[n/2]}else{(x[n/2-1]+x[n/2])/2.}}
fn gm(x:&[f64])->f64{assert!(!x.is_empty());(x.iter().map(|v|{assert!(*v>0.);v.ln()}).sum::<f64>()/x.len()as f64).exp()}
fn main(){let r=Path::new("/tmp/zopro-g2-tree-sdk");let data=r.join("remote-results/output/measure/performance");let config=read(r.join("remote-results/output/measure/config.json"));assert_eq!(read(data.join("result.json"))["status"],"complete");assert_eq!(read(r.join("remote-results/output/measure/complete.json"))["sdk_requests"],7416);let rows=read(data.join("rows.json"));let rows=rows.as_array().unwrap();assert_eq!(rows.len(),332);let manifest=read(r.join("context/manifest.json"));let mut prior:BTreeSet<String>=serde_json::from_value(manifest["prior_proof_sha256"].clone()).unwrap();assert_eq!(prior.len(),5958);let mut inventory=BTreeMap::new();let verify=r.join("local-verification-proofs");fs::create_dir(&verify).unwrap();
 let mut add=|p:&Path,name:&str,public_sha:&str|{assert_eq!(fs::metadata(p).unwrap().len(),164);let h=hash(p);assert!(prior.insert(h.clone()),"repeated proof");assert_eq!(hash(p.with_extension("public")),public_sha);let stem=p.parent().unwrap().file_name().unwrap();let d=verify.join(stem);fs::create_dir_all(&d).unwrap();fs::hard_link(p,d.join(format!("{name}.proof"))).unwrap();fs::hard_link(p.with_extension("public"),d.join(format!("{name}.public"))).unwrap();for p in [p.to_path_buf(),p.with_extension("public")]{inventory.insert(p.display().to_string(),hash(p));}};
 let preflight=read(r.join("local-output/preflight/proof-inventory.json"));assert_eq!(preflight.as_object().unwrap().len(),82);for(p,h)in preflight.as_object().unwrap(){if p.ends_with(".proof"){let local=r.join("local-output").join(p.strip_prefix("/output/").unwrap());assert_eq!(hash(&local),h.as_str().unwrap());let stem=local.parent().unwrap().file_name().unwrap();let c=config["cases"].as_array().unwrap().iter().find(|c|Path::new(c["image"].as_str().unwrap()).file_stem().unwrap()==stem).unwrap();let tag=local.parent().unwrap().parent().unwrap().file_name().unwrap().to_str().unwrap();add(&local,&format!("preflight-{tag}"),c["public_sha256"].as_str().unwrap());}}
 let mut sdk=164;let mut profiles=BTreeMap::new();let mut samples=0;for row in rows{let c=config["cases"].as_array().unwrap().iter().find(|c|c["name"]==row["case"]).unwrap();let phase=row["phase"].as_str().unwrap();let engine=row["variant"].as_str().unwrap();let name=row["case"].as_str().unwrap();let block=row["block"].as_u64().unwrap();let rounds=if phase=="profile"{51}else if c["shape"]=="1x2"{31}else{17};assert_eq!(row["samples_ms"].as_array().unwrap().len(),rounds);assert_eq!(row["summary"]["rounds"],rounds);assert_eq!(row["summary"]["workers"],c["workers"]);sdk+=rounds+3;let stem=Path::new(c["image"].as_str().unwrap()).file_stem().unwrap();let p=data.join(format!("{phase}/b{block}/{name}/{engine}/proofs")).join(stem).join("0.proof");add(&p,&format!("{phase}-b{block}-{name}-{engine}"),c["public_sha256"].as_str().unwrap());if phase=="profile"{assert_eq!(row["profile"]["lost_records"],0);assert_eq!(row["profile"]["sampled_pids"].as_array().unwrap().len(),1);samples+=row["profile"]["samples"].as_u64().unwrap();profiles.insert(format!("{name}/{engine}"),row["profile"].clone());}}
 assert_eq!(sdk,7580);assert_eq!(inventory.len(),746);assert_eq!(prior.len(),6331);for(p,h)in read(data.join("proof-inventory.json")).as_object().unwrap(){assert_eq!(hash(data.join(p)),h.as_str().unwrap());}save(r.join("proof-inventory.json"),&json!(inventory));let log=fs::File::create(r.join("post-transport-gnark.log")).unwrap();assert!(Command::new("/tmp/zopro-gnark-verify/verify").args(["/tmp/zopro-keys",verify.to_str().unwrap(),"/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock"]).stdout(Stdio::from(log.try_clone().unwrap())).stderr(Stdio::from(log)).status().unwrap().success());assert!(fs::read_to_string(r.join("post-transport-gnark.log")).unwrap().lines().last().unwrap().contains("verified 373 distinct proofs across 9 pinned keys"));
 let mut cases=BTreeMap::new();let mut calibration=Vec::new();let mut primary=Vec::new();let mut regressions=Vec::new();let mut original:BTreeMap<u64,(Vec<f64>,Vec<f64>)>=BTreeMap::new();
 for c in config["cases"].as_array().unwrap(){let name=c["name"].as_str().unwrap();let workers=c["workers"].as_u64().unwrap();let target=workers!=32;let mut engines=BTreeMap::new();for engine in ["accepted","off","on","aeglos"]{let selected:Vec<_>=rows.iter().filter(|row|row["case"]==name&&row["variant"]==engine&&row["phase"]=="latency").collect();assert_eq!(selected.len(),3);let cpu=median(selected.iter().map(|row|(row["summary"]["user_cpu_ms"].as_f64().unwrap()+row["summary"]["system_cpu_ms"].as_f64().unwrap())/row["summary"]["rounds"].as_f64().unwrap()).collect());let rss=selected.iter().map(|row|row["summary"]["whole_process_maxrss_kib"].as_f64().unwrap()/1024.).fold(0.,f64::max);let mut stages=BTreeMap::new();if engine=="aeglos"{for key in ["witness_ms","fft_ms","msm_ms","assembly_ms","native_bytes","request_minus_msm_ms"]{let mut values=Vec::new();for row in &selected{let d=data.join(format!("latency/b{}/{name}/{engine}/proofs",row["block"].as_u64().unwrap())).join(Path::new(c["image"].as_str().unwrap()).file_stem().unwrap());let s=fs::read_to_string(d.join("driver.stdout")).unwrap();let samples:Vec<Value>=s.lines().filter_map(|s|s.strip_prefix("SAMPLE ")).map(|s|serde_json::from_str(s).unwrap()).collect();assert_eq!(samples.len(),c["rounds"].as_u64().unwrap()as usize);values.push(median(samples.iter().map(|s|if key=="request_minus_msm_ms"{s["verified_ms"].as_f64().unwrap()-s["msm_ms"].as_f64().unwrap()}else{s[key].as_f64().unwrap()}).collect()));}stages.insert(key,median(values));}}
 engines.insert(engine,json!({"request_ms":median(selected.iter().map(|r|r["median_ms"].as_f64().unwrap()).collect()),"CPU_ms_per_request":cpu,"maximum_whole_process_RSS_mib":rss,"stages":stages}));}
 let mut off=Vec::new();let mut on_off=Vec::new();let mut on_acc=Vec::new();for block in 0..3{let ms=|v:&str|rows.iter().find(|row|row["case"]==name&&row["variant"]==v&&row["phase"]=="latency"&&row["block"]==block).unwrap()["median_ms"].as_f64().unwrap();off.push(ms("off")/ms("accepted"));on_off.push(ms("on")/ms("off"));on_acc.push(ms("on")/ms("accepted"));if !(1./1.05..=1.05).contains(off.last().unwrap()){calibration.push(format!("{name} b{block} OFF/accepted={}",off.last().unwrap()));}}
 let off_med=median(off.clone());if !(1./1.03..=1.03).contains(&off_med){calibration.push(format!("{name} paired OFF/accepted={off_med}"));}let co=gm(&on_off);let ca=gm(&on_acc);if target&&c["shape"]=="1x2"{for(label,ratios)in[("ON/OFF",&on_off),("ON/accepted",&on_acc)]{let ratio=gm(ratios);let wins=ratios.iter().filter(|x|**x<1.).count();if ratio>=1.||wins<2{primary.push(format!("{name} {label}={ratio}, wins{wins}"));}}}else{if co>1.02{regressions.push(format!("{name} ON/OFF={co}"));}if ca>1.02{regressions.push(format!("{name} ON/accepted={ca}"));}}if c["shape"]!="merge-54x1"{let entry=original.entry(workers).or_default();entry.0.push(co);entry.1.push(ca);}
 cases.insert(name,json!({"shape":c["shape"],"workers":workers,"engines":engines,"off_accepted_block_ratios":off,"off_accepted_paired_median":off_med,"on_off_block_ratios":on_off,"on_accepted_block_ratios":on_acc,"on_off_geomean":co,"on_accepted_geomean":ca,"reference":c["reference"]}));
 }
 let mut aggregate=BTreeMap::new();let mut aggregate_failures=Vec::new();for(workers,(off,acc))in original{assert_eq!(off.len(),8);let a=gm(&off);let b=gm(&acc);aggregate.insert(workers,json!({"on_off_geomean":a,"on_accepted_geomean":b}));if a>1.||b>1.{aggregate_failures.push(format!("w{workers} ON/OFF={a}, ON/accepted={b}"));}}
 let cross:Vec<f64>=(0..3).map(|block|{let ms=|case:&str,variant:&str|rows.iter().find(|r|r["phase"]=="latency"&&r["case"]==case&&r["variant"]==variant&&r["block"]==block).unwrap()["median_ms"].as_f64().unwrap();ms("1x2-w64","on")/ms("1x2-w32","accepted")}).collect();let cross_ratio=gm(&cross);let cross_wins=cross.iter().filter(|x|**x<1.).count();if cross_ratio>=1.||cross_wins<2{primary.push(format!("primaryON64/accepted32={cross_ratio},wins{cross_wins}/3"));}
 let passed=calibration.is_empty()&&primary.is_empty()&&regressions.is_empty()&&aggregate_failures.is_empty();let result=json!({"status":"complete independently verified C7a comparison","sdk_requests":sdk,"distinct_gnark_exports":373,"proof_public_members":746,"latency_processes":324,"profile_processes":8,"profile_samples":samples,"profiles":profiles,"lost_records":0,"calibration_failures":calibration,"primary_failures":primary,"regressions":regressions,"aggregate_failures":aggregate_failures,"primary_ON64_accepted32":{"block_ratios":cross,"paired_geomean":cross_ratio,"wins":cross_wins},"target_adoption_gate_passed":passed,"cases":cases,"original_eight_aggregates":aggregate,"post_transport_gnark_verified":373,"next_prior_proof_count":6331,"adopted":false,"goal_achieved":false});save(r.join("analysis.json"),&result);println!("Verified7580SDK373Gnark746members;{}cyclesamples; targetgate{passed}",samples);}
